 for(const kind of sourceCases)await check('source-reject-'+kind,async()=>{const output=path.join(evidence,'source-negative-'+kind),argv=[driver,'--manifest',real.manifest_ref.path,'--source-negative-probe',kind,'--output',output],child=spawnSync(process.execPath,argv,{cwd:repo,encoding:'utf8',timeout:15000});fs.writeFileSync(path.join(evidence,'source-'+kind+'.stdout.txt'),child.stdout||'');fs.writeFileSync(path.join(evidence,'source-'+kind+'.stderr.txt'),child.stderr||'');write(path.join(evidence,'source-'+kind+'-command.json'),{argv:[process.execPath,...argv],cwd:repo,exit_code:child.status,signal:child.signal});assert.equal(child.status,1);assert.match(child.stderr,/EXPECTED_SOURCE_REJECTION/);return {kind,exit_code:child.status,before_browser:true};});
