  await session(engine,'u008-reopen-two',second.html,(page,loc,record)=>check(engine+'-u008-current-reopen-two',async()=>{assert.deepEqual(await adapter.observe(page),baseline.initial);await preserve(second.html);await click(page,'交互说明');assert.equal(await page.locator('[data-card]').count(),noteCount);await click(page,'关闭说明');await page.locator('[data-nav="projects"]').click();assert.equal(await page.locator('h1').textContent(),'项目管理');return {download_ref:second.ref,total_notes:noteCount,identical_download_sha256:hash(second.html),fresh_directory_profile:true,offline:true};}));
