  const output=path.join(evidence,'source-negative-'+kind),argv=[driver,'--manifest',real.manifest_ref.path,'--source-negative-probe',kind,'--output',output];
  const child=spawnSync(process.execPath,argv,{cwd:repo,encoding:'utf8',timeout:15000});
  const stdout=path.join(evidence,'source-'+kind+'.stdout.txt'),stderr=path.join(evidence,'source-'+kind+'.stderr.txt');fs.writeFileSync(stdout,child.stdout||'');fs.writeFileSync(stderr,child.stderr||'');
  write(path.join(evidence,'source-'+kind+'-command.json'),{argv:[process.execPath,...argv],cwd:repo,exit_code:child.status,signal:child.signal});
