    const title=await page.locator('#drawer-title').boundingBox();await record('notes: pick visible detail title without business click',()=>page.mouse.click(title.x+10,title.y+title.height/2));
    await page.getByRole('textbox',{name:'标题',exact:true}).fill('项目详情标题');await page.getByRole('textbox',{name:'主说明',exact:true}).fill('当前原型：详情顶部显示所选项目名称。');await click(page,'完成编辑');
    const after=await adapter.observe(page);for(const key of ['board','board_text','drawer','drawer_title','inert','modal_count','scroll','drawer_scroll'])assert.deepEqual(after[key],stable[key],key+' unchanged by picker');
    await click(page,'编辑 2');await page.getByRole('textbox',{name:'主说明',exact:true}).fill('当前原型：详情顶部显示所选项目名称；关闭详情后返回项目清单。');await click(page,'完成编辑');
    await page.screenshot({path:path.join(loc,'real-custom-modal.png')});await click(page,'关闭说明');const closed=await adapter.closeDrawer({page,record});assert.equal(closed.inert,false);assert.match(closed.focus.action,/^open-project:/);
    await click(page,'交互说明');assert.equal(await page.locator('[data-card]').count(),2);assert.equal(await page.locator('[data-location]').count(),0);assert.equal(await page.getByRole('button',{name:'说明 2：项目详情标题',exact:true}).count(),0);
